                                        svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="80" text-anchor="middle" fill="#8b5cf6" font-weight="bold" font-size="42">TWO TYPES OF ANCHORING</text><text x="550" y="120" text-anchor="middle" fill="#888" font-size="26">Both System 1 and System 2 are affected</text><rect x="60" y="170" width="470" height="430" rx="20" fill="rgba(99,102,241,0.15)" stroke="#6366f1" stroke-width="3"/><text x="295" y="220" text-anchor="middle" fill="#6366f1" font-weight="bold" font-size="28">TYPE 1: ADJUSTMENT</text><text x="295" y="265" text-anchor="middle" fill="#888" font-size="22">(System 2)</text><text x="295" y="320" text-anchor="middle" fill="#fff" font-size="22">Start at anchor and</text><text x="295" y="355" text-anchor="middle" fill="#fff" font-size="22">deliberately adjust</text><rect x="120" y="390" width="290" height="80" rx="10" fill="rgba(99,102,241,0.2)"/><text x="265" y="440" text-anchor="middle" fill="#fff" font-size="20">Adjustment is effortful</text><text x="295" y="510" text-anchor="middle" fill="#ef4444" font-size="22">Like a rubber band -</text><text x="295" y="545" text-anchor="middle" fill="#ef4444" font-size="22">anchor pulls you back</text><rect x="570" y="170" width="470" height="430" rx="20" fill="rgba(239,68,68,0.15)" stroke="#ef4444" stroke-width="3"/><text x="805" y="220" text-anchor="middle" fill="#ef4444" font-weight="bold" font-size="28">TYPE 2: PRIMING</text><text x="805" y="265" text-anchor="middle" fill="#888" font-size="22">(System 1)</text><text x="805" y="320" text-anchor="middle" fill="#fff" font-size="22">Anchor activates</text><text x="805" y="355" text-anchor="middle" fill="#fff" font-size="22">compatible information</text><rect x="630" y="390" width="290" height="80" rx="10" fill="rgba(239,68,68,0.2)"/><text x="775" y="440" text-anchor="middle" fill="#fff" font-size="20">Happens automatically</text><text x="805" y="510" text-anchor="middle" fill="#f59e0b" font-size="22">"Is Gandhi older than 144?"</text><text x="805" y="545" text-anchor="middle" fill="#888" font-size="20">Primes: old, wisdom, longevity</text><rect x="150" y="620" width="800" height="150" rx="20" fill="rgba(245,158,11,0.15)" stroke="#f59e0b" stroke-width="3"/><text x="550" y="680" text-anchor="middle" fill="#f59e0b" font-weight="bold" font-size="26">BOTH MECHANISMS WORK TOGETHER</text><text x="550" y="730" text-anchor="middle" fill="#fff" font-size="22">Making anchoring one of the most robust cognitive biases</text></svg>`,
