                                        type: "diagram",
                                        svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" fill="#ffd700" font-weight="bold" font-size="42">TECHNICAL SAFEGUARDS</text><text x="550" y="100" text-anchor="middle" fill="#888" font-size="29">Required (R) vs Addressable (A)</text><rect x="80" y="150" width="940" height="55" rx="12" fill="rgba(239,68,68,0.12)" stroke="#ef4444" stroke-width="2"/><text x="120" y="185" text-anchor="start" fill="#ef4444" font-weight="bold" font-size="18">(R)</text><text x="160" y="185" text-anchor="start" fill="#fff" font-size="19">Unique user identification</text><text x="700" y="185" text-anchor="start" fill="#ef4444" font-size="16">NO shared logins</text><rect x="80" y="220" width="940" height="55" rx="12" fill="rgba(239,68,68,0.12)" stroke="#ef4444" stroke-width="2"/><text x="120" y="255" text-anchor="start" fill="#ef4444" font-weight="bold" font-size="18">(R)</text><text x="160" y="255" text-anchor="start" fill="#fff" font-size="19">Emergency access procedure</text><rect x="80" y="290" width="940" height="55" rx="12" fill="rgba(239,68,68,0.12)" stroke="#ef4444" stroke-width="2"/><text x="120" y="325" text-anchor="start" fill="#ef4444" font-weight="bold" font-size="18">(R)</text><text x="160" y="325" text-anchor="start" fill="#fff" font-size="19">Audit controls</text><rect x="80" y="360" width="940" height="55" rx="12" fill="rgba(239,68,68,0.12)" stroke="#ef4444" stroke-width="2"/><text x="120" y="395" text-anchor="start" fill="#ef4444" font-weight="bold" font-size="18">(R)</text><text x="160" y="395" text-anchor="start" fill="#fff" font-size="19">Person or entity authentication</text><rect x="80" y="450" width="940" height="55" rx="12" fill="rgba(245,158,11,0.1)" stroke="#f59e0b" stroke-width="1.5"/><text x="120" y="485" text-anchor="start" fill="#f59e0b" font-weight="bold" font-size="18">(A)</text><text x="160" y="485" text-anchor="start" fill="#fff" font-size="19">Automatic logoff</text><rect x="80" y="520" width="940" height="55" rx="12" fill="rgba(245,158,11,0.1)" stroke="#f59e0b" stroke-width="1.5"/><text x="120" y="555" text-anchor="start" fill="#f59e0b" font-weight="bold" font-size="18">(A)</text><text x="160" y="555" text-anchor="start" fill="#fff" font-size="19">Encryption and decryption (at rest)</text><rect x="80" y="590" width="940" height="55" rx="12" fill="rgba(245,158,11,0.1)" stroke="#f59e0b" stroke-width="1.5"/><text x="120" y="625" text-anchor="start" fill="#f59e0b" font-weight="bold" font-size="18">(A)</text><text x="160" y="625" text-anchor="start" fill="#fff" font-size="19">Mechanism to authenticate ePHI integrity</text><rect x="80" y="660" width="940" height="55" rx="12" fill="rgba(245,158,11,0.1)" stroke="#f59e0b" stroke-width="1.5"/><text x="120" y="695" text-anchor="start" fill="#f59e0b" font-weight="bold" font-size="18">(A)</text><text x="160" y="695" text-anchor="start" fill="#fff" font-size="19">Transmission security (integrity + encryption)</text></svg>`,
