                                {
                                    type: "quiz",
                                    question: "A health information manager knows the right course of action in an ethical dilemma but is pressured by their supervisor to act differently. This experience is BEST described as:",
                                    options: [
                                        { text: "An ethical violation, because knowing the right action and not taking it is always wrong", correct: false },
                                        { text: "Moral distress, because the individual knows the right action but is constrained from taking it", correct: true },
                                        { text: "An ethical dilemma, because two competing principles are in conflict", correct: false },
                                        { text: "Professional misconduct, because compliance with supervisor instructions is always required", correct: false }
                                    ],
                                    explanation: "Moral distress occurs when a person knows the ethically correct action but feels constrained from taking it — by institutional policies, authority figures, time pressure, or systemic barriers. This is different from an ethical dilemma (where the right course of action is unclear because principles conflict). Moral distress is recognized as a significant issue in healthcare that can lead to burnout, job dissatisfaction, and ultimately harm to patients if ethical actions are consistently suppressed. The correct response is to seek support through ethics committees, compliance channels, or professional organizations.",
                                    visual: {
                                        type: "diagram",
                                        svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" fill="#ffd700" font-weight="bold" font-size="42">MORAL DISTRESS</text><text x="550" y="100" text-anchor="middle" fill="#888" font-size="29">Knowing the Right Action but Being Constrained</text><rect x="150" y="200" width="350" height="120" rx="20" fill="rgba(99,102,241,0.12)" stroke="#6366f1" stroke-width="2"/><text x="325" y="250" text-anchor="middle" fill="#6366f1" font-weight="bold" font-size="22">Ethical Dilemma</text><text x="325" y="285" text-anchor="middle" fill="#fff" font-size="16">Right action is UNCLEAR</text><text x="325" y="305" text-anchor="middle" fill="#888" font-size="14">Principles in conflict</text><rect x="600" y="200" width="350" height="120" rx="20" fill="rgba(239,68,68,0.12)" stroke="#ef4444" stroke-width="2"/><text x="775" y="250" text-anchor="middle" fill="#ef4444" font-weight="bold" font-size="22">Moral Distress</text><text x="775" y="285" text-anchor="middle" fill="#fff" font-size="16">Right action is KNOWN</text><text x="775" y="305" text-anchor="middle" fill="#888" font-size="14">But constrained from acting</text></svg>`,
                                        caption: "Moral distress vs ethical dilemma — knowing vs not knowing the right action"
                                    }
                                }
