                                    type: "quiz",
                                    question: "A patient is admitted Friday evening and expected to discharge Sunday morning. Per the Two-Midnight Rule, what is the appropriate status?",
                                    options: [
                                        { text: "Inpatient - patient is in hospital over weekend", correct: false },
                                        { text: "Observation - stay doesn't span two midnights", correct: false },
                                        { text: "Inpatient - stay spans two midnights (Fri-Sat, Sat-Sun)", correct: true },
                                        { text: "Depends on diagnosis only", correct: false }
                                    ],
                                    explanation: "Friday evening to Sunday morning spans two midnights (Friday-Saturday and Saturday-Sunday), meeting the Two-Midnight Rule criteria for inpatient admission."
