                                    content: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg">
                                        <rect width="800" height="380" fill="#1a1a2e"/>
                                        <text x="628" y="110" fill="#00d4ff" font-size="42" text-anchor="middle" font-weight="bold">Leadership Style Spectrum</text>
                                        <rect x="78" y="220" width="345" height="476" fill="#5a2d4a" rx="15"/>
                                        <text x="251" y="311" fill="#ff6b6b" font-size="31" text-anchor="middle" font-weight="bold">Autocratic</text>
                                        <text x="110" y="403" fill="#ffffff" font-size="25">• Leader makes all decisions</text>
                                        <text x="110" y="469" fill="#ffffff" font-size="25">• Close supervision</text>
                                        <text x="110" y="535" fill="#ffffff" font-size="25">• Top-down communication</text>
                                        <text x="110" y="616" fill="#ffd700" font-size="25">Best for: Crisis, new staff,</text>
                                        <text x="110" y="671" fill="#ffd700" font-size="25">strict compliance needs</text>
                                        <rect x="455" y="220" width="345" height="476" fill="#4a5568" rx="15"/>
                                        <text x="628" y="311" fill="#ffd700" font-size="31" text-anchor="middle" font-weight="bold">Democratic</text>
                                        <text x="487" y="403" fill="#ffffff" font-size="25">• Shared decision-making</text>
                                        <text x="487" y="469" fill="#ffffff" font-size="25">• Team input valued</text>
                                        <text x="487" y="535" fill="#ffffff" font-size="25">• Two-way communication</text>
                                        <text x="487" y="616" fill="#ffd700" font-size="25">Best for: Experienced teams,</text>
                                        <text x="487" y="671" fill="#ffd700" font-size="25">complex problems</text>
                                        <rect x="832" y="220" width="345" height="476" fill="#2d5a4a" rx="15"/>
                                        <text x="1005" y="311" fill="#00ff88" font-size="31" text-anchor="middle" font-weight="bold">Laissez-faire</text>
                                        <text x="864" y="403" fill="#ffffff" font-size="25">• Minimal supervision</text>
                                        <text x="864" y="469" fill="#ffffff" font-size="25">• Staff autonomy</text>
                                        <text x="864" y="535" fill="#ffffff" font-size="25">• Hands-off approach</text>
                                        <text x="864" y="616" fill="#ffd700" font-size="25">Best for: Expert self-directed</text>
                                        <text x="864" y="671" fill="#ffd700" font-size="25">professionals</text>
                                        <rect x="78" y="770" width="700" height="550" fill="#2d3a4a" rx="15"/>
                                        <text x="110" y="861" fill="#00d4ff" font-size="31" font-weight="bold">Key Management Theories:</text>
                                        <text x="110" y="953" fill="#ffffff" font-size="28">• Taylor (Scientific Management): Time studies, standardization, efficiency</text>
                                        <text x="110" y="1026" fill="#ffffff" font-size="28">• Maslow (Hierarchy of Needs): Physiological â†’ Safety â†’ Social â†’ Esteem â†’ Self-actualization</text>
                                        <text x="110" y="1100" fill="#ffffff" font-size="28">• Herzberg (Two-Factor): Hygiene factors (prevent dissatisfaction) vs Motivators (create satisfaction)</text>
                                        <text x="110" y="1173" fill="#ffffff" font-size="28">• McGregor (Theory X/Y): X=workers avoid work, need control; Y=workers self-motivated</text>
                                        <text x="110" y="1246" fill="#ffd700" font-size="28">• Situational Leadership (Hersey-Blanchard): Adapt style to follower readiness level</text>
                                    </svg>`
