        visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" font-size="42" fill="#ffd700" text-anchor="middle" font-weight="bold">Quiz: Quantitative Analysis</text><text x="550" y="100" font-size="29" fill="#888" text-anchor="middle">The Completeness Check</text><rect x="60" y="140" width="980" height="200" rx="18" fill="#23234a"/><text x="100" y="180" font-size="24" fill="#10b981" font-weight="bold">Quantitative Analysis Checks For:</text><text x="100" y="220" font-size="22" fill="#fff">1. All required reports PRESENT in the record</text><text x="100" y="255" font-size="22" fill="#fff">2. All entries properly AUTHENTICATED (signature + date + credentials)</text><text x="100" y="290" font-size="22" fill="#fff">3. Patient properly IDENTIFIED on all forms (name + MRN)</text><text x="100" y="325" font-size="22" fill="#fff">4. Record in correct CHART ORDER per facility policy</text><rect x="60" y="370" width="980" height="100" rx="15" fill="rgba(255,215,0,0.15)" stroke="#ffd700" stroke-width="2"/><text x="100" y="410" font-size="22" fill="#ffd700" font-weight="bold">Memory Key</text><text x="100" y="445" font-size="22" fill="#fff">QUANTITATIVE = Is it THERE? | QUALITATIVE = Is it GOOD?</text></svg>`, caption: "Quantitative analysis: the completeness checklist for discharged records" }
