  cards: [
    {
      type: "intro",
      title: "Revenue Cycle: Front End to Back End",
      content: "The revenue cycle is the complete lifecycle of a patient account from the moment a patient schedules an appointment to the final payment collection. It encompasses every financial transaction between the patient, provider, and payer. HIM professionals touch nearly every phase — from coding and charge capture to claim submission, denial management, and compliance monitoring. This lesson maps the entire revenue cycle flow, defines critical performance metrics, explains the Medicare appeals process, and covers Clinical Documentation Improvement (CDI) programs. Expect 6-8 RHIT questions on revenue cycle operations, metrics, and CDI.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Revenue Cycle Management</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Front End → Middle → Back End</text><rect x="60" y="140" width="300" height="300" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="210" y="180" text-anchor="middle" font-size="24" fill="#10b981" font-weight="bold">Front End</text><text x="80" y="215" font-size="18" fill="#fff">Scheduling</text><text x="80" y="245" font-size="18" fill="#fff">Pre-registration</text><text x="80" y="275" font-size="18" fill="#fff">Insurance verification</text><text x="80" y="305" font-size="18" fill="#fff">Pre-authorization</text><text x="80" y="335" font-size="18" fill="#fff">Registration</text><text x="80" y="365" font-size="18" fill="#fff">Patient access</text><text x="80" y="400" font-size="16" fill="#888">Before/during service</text><rect x="400" y="140" width="300" height="300" rx="18" fill="#23234a" stroke="#f59e0b" stroke-width="2"/><text x="550" y="180" text-anchor="middle" font-size="24" fill="#f59e0b" font-weight="bold">Middle</text><text x="420" y="215" font-size="18" fill="#fff">Charge capture (CDM)</text><text x="420" y="245" font-size="18" fill="#fff">Coding (HIM)</text><text x="420" y="275" font-size="18" fill="#fff">Claim scrubbing</text><text x="420" y="305" font-size="18" fill="#fff">Claim submission (837)</text><text x="420" y="335" font-size="18" fill="#fff">CDI review</text><text x="420" y="365" font-size="18" fill="#fff">Physician queries</text><text x="420" y="400" font-size="16" fill="#888">During/after service</text><rect x="740" y="140" width="300" height="300" rx="18" fill="#23234a" stroke="#ef4444" stroke-width="2"/><text x="890" y="180" text-anchor="middle" font-size="24" fill="#ef4444" font-weight="bold">Back End</text><text x="760" y="215" font-size="18" fill="#fff">Remittance (835)</text><text x="760" y="245" font-size="18" fill="#fff">Payment posting</text><text x="760" y="275" font-size="18" fill="#fff">Denial management</text><text x="760" y="305" font-size="18" fill="#fff">Appeals</text><text x="760" y="335" font-size="18" fill="#fff">Collections</text><text x="760" y="365" font-size="18" fill="#fff">A/R follow-up</text><text x="760" y="400" font-size="16" fill="#888">After claim processing</text><line x1="360" y1="290" x2="400" y2="290" stroke="#ffd700" stroke-width="3"/><line x1="700" y1="290" x2="740" y2="290" stroke="#ffd700" stroke-width="3"/><rect x="60" y="480" width="980" height="100" rx="15" fill="rgba(255,215,0,0.08)" stroke="#ffd700" stroke-width="2"/><text x="100" y="520" font-size="22" fill="#ffd700" font-weight="bold">Key Metrics You Must Know</text><text x="100" y="555" font-size="20" fill="#fff">Days in A/R, Clean Claim Rate, Denial Rate, DNFB, DNFC, CMI</text></svg>`, caption: "Revenue cycle overview: front end, middle, and back end operations" }
    },
    {
      type: "concept",
      title: "Front End: Scheduling Through Registration",
      content: "The front end of the revenue cycle sets the foundation for clean claims and timely payment. It begins with scheduling, where the appointment type and provider are established. Pre-registration collects demographic and insurance information before the patient arrives — this saves time and allows staff to begin verification. Insurance verification confirms the patient's coverage is active, checks benefits and deductibles, and identifies copay amounts. Pre-authorization (also called prior authorization or precertification) obtains approval from the payer before certain services are rendered — failure to obtain required pre-auth is one of the top denial reasons. Registration (patient access) finalizes demographic data, collects signatures, distributes notices (HIPAA NPP, ABN if applicable, consent forms), scans insurance cards, and collects point-of-service payments (copays). The MSP questionnaire is completed here to determine Medicare payer order. Errors at the front end cascade through the entire cycle — incorrect insurance information leads to claim denials, delayed payments, and increased A/R days.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Front End Revenue Cycle</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Scheduling Through Registration</text><rect x="60" y="140" width="200" height="100" rx="12" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="160" y="185" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Scheduling</text><text x="160" y="210" text-anchor="middle" font-size="16" fill="#fff">Appt type +</text><text x="160" y="228" text-anchor="middle" font-size="16" fill="#fff">provider</text><line x1="260" y1="190" x2="290" y2="190" stroke="#ffd700" stroke-width="2"/><rect x="290" y="140" width="200" height="100" rx="12" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="390" y="185" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Pre-Reg</text><text x="390" y="210" text-anchor="middle" font-size="16" fill="#fff">Demographics +</text><text x="390" y="228" text-anchor="middle" font-size="16" fill="#fff">insurance info</text><line x1="490" y1="190" x2="520" y2="190" stroke="#ffd700" stroke-width="2"/><rect x="520" y="140" width="200" height="100" rx="12" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="620" y="185" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Verification</text><text x="620" y="210" text-anchor="middle" font-size="16" fill="#fff">Coverage active?</text><text x="620" y="228" text-anchor="middle" font-size="16" fill="#fff">Benefits + copay</text><line x1="720" y1="190" x2="750" y2="190" stroke="#ffd700" stroke-width="2"/><rect x="750" y="140" width="280" height="100" rx="12" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="890" y="175" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Pre-Authorization</text><text x="890" y="200" text-anchor="middle" font-size="16" fill="#fff">Payer approval for</text><text x="890" y="218" text-anchor="middle" font-size="16" fill="#fff">specific services</text><rect x="300" y="270" width="500" height="100" rx="12" fill="#23234a" stroke="#ffd700" stroke-width="2"/><text x="550" y="310" text-anchor="middle" font-size="24" fill="#ffd700" font-weight="bold">Registration / Patient Access</text><text x="550" y="340" text-anchor="middle" font-size="18" fill="#fff">Finalize demographics, collect copay, MSP questionnaire</text><line x1="550" y1="240" x2="550" y2="270" stroke="#ffd700" stroke-width="2"/><rect x="60" y="400" width="980" height="230" rx="18" fill="#23234a"/><text x="100" y="440" font-size="22" fill="#f59e0b" font-weight="bold">Registration Checklist</text><text x="100" y="475" font-size="19" fill="#fff">1. Verify/update demographics and insurance information</text><text x="100" y="505" font-size="19" fill="#fff">2. Collect patient signatures (consent, financial responsibility)</text><text x="100" y="535" font-size="19" fill="#fff">3. Distribute HIPAA Notice of Privacy Practices (NPP)</text><text x="100" y="565" font-size="19" fill="#fff">4. Issue ABN (Advance Beneficiary Notice) if service may not be covered</text><text x="100" y="595" font-size="19" fill="#fff">5. Complete MSP questionnaire for Medicare patients</text><text x="100" y="625" font-size="19" fill="#fff">6. Collect point-of-service payment (copay/coinsurance/deductible)</text><rect x="60" y="660" width="980" height="80" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="100" y="700" font-size="22" fill="#ef4444" font-weight="bold">Missing pre-authorization = #1 preventable denial reason</text><text x="100" y="728" font-size="19" fill="#fff">Front-end errors cascade through the ENTIRE revenue cycle</text></svg>`, caption: "Front-end revenue cycle steps and registration checklist" }
    },
    {
      type: "concept",
      title: "Middle: Charge Capture Through Claim Submission",
      content: "After services are rendered, the middle revenue cycle converts clinical services into billable claims. Charge capture links services provided to charges in the Chargemaster/CDM — nurses, technicians, and clinicians document services which automatically generate charges. HIM coders then assign ICD-10-CM/PCS and CPT/HCPCS codes based on clinical documentation. CDI specialists review records concurrently (during the stay) to ensure documentation supports the acuity and complexity of care, issuing compliant physician queries when clarification is needed. Claim scrubbing uses automated software (code editors) to check claims for errors before submission — verifying code validity, checking NCCI edits, confirming medical necessity, and flagging missing information. Clean claims (those passing all edits) are submitted electronically: 837I for institutional claims (UB-04) and 837P for professional claims (CMS-1500). DNFB (Discharged Not Final Billed) tracks accounts where the patient has been discharged but the claim has not yet been submitted — high DNFB delays cash flow. DNFC (Discharged Not Final Coded) tracks accounts awaiting coding completion.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Middle Revenue Cycle</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Charge Capture → Coding → Claim Submission</text><rect x="60" y="140" width="310" height="170" rx="15" fill="#23234a" stroke="#f59e0b" stroke-width="2"/><text x="215" y="175" text-anchor="middle" font-size="22" fill="#f59e0b" font-weight="bold">Charge Capture</text><text x="80" y="210" font-size="18" fill="#fff">Clinical services → CDM</text><text x="80" y="238" font-size="18" fill="#fff">Auto-generated charges</text><text x="80" y="266" font-size="18" fill="#fff">from clinical documentation</text><text x="80" y="294" font-size="16" fill="#888">Nurses + techs + clinicians</text><line x1="370" y1="225" x2="395" y2="225" stroke="#ffd700" stroke-width="2"/><rect x="395" y="140" width="310" height="170" rx="15" fill="#23234a" stroke="#8b5cf6" stroke-width="2"/><text x="550" y="175" text-anchor="middle" font-size="22" fill="#8b5cf6" font-weight="bold">Coding (HIM)</text><text x="415" y="210" font-size="18" fill="#fff">ICD-10-CM/PCS assignment</text><text x="415" y="238" font-size="18" fill="#fff">CPT/HCPCS assignment</text><text x="415" y="266" font-size="18" fill="#fff">Concurrent CDI review</text><text x="415" y="294" font-size="16" fill="#888">Physician queries as needed</text><line x1="705" y1="225" x2="730" y2="225" stroke="#ffd700" stroke-width="2"/><rect x="730" y="140" width="310" height="170" rx="15" fill="#23234a" stroke="#3b82f6" stroke-width="2"/><text x="885" y="175" text-anchor="middle" font-size="22" fill="#3b82f6" font-weight="bold">Claim Scrubbing</text><text x="750" y="210" font-size="18" fill="#fff">Automated error checking</text><text x="750" y="238" font-size="18" fill="#fff">NCCI edits, code validity</text><text x="750" y="266" font-size="18" fill="#fff">Medical necessity check</text><text x="750" y="294" font-size="16" fill="#888">Catch errors before submission</text><rect x="300" y="340" width="500" height="80" rx="15" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="550" y="380" text-anchor="middle" font-size="24" fill="#10b981" font-weight="bold">Claim Submission</text><text x="550" y="405" text-anchor="middle" font-size="18" fill="#fff">837I (Institutional) | 837P (Professional)</text><line x1="550" y1="310" x2="550" y2="340" stroke="#ffd700" stroke-width="2"/><rect x="60" y="460" width="480" height="140" rx="15" fill="#23234a" stroke="#ef4444" stroke-width="2"/><text x="100" y="500" font-size="22" fill="#ef4444" font-weight="bold">DNFB — Discharged Not Final Billed</text><text x="100" y="535" font-size="19" fill="#fff">Patient discharged but claim NOT yet sent</text><text x="100" y="565" font-size="19" fill="#fff">High DNFB = delayed cash flow</text><text x="100" y="590" font-size="16" fill="#888">Target: minimize DNFB days</text><rect x="560" y="460" width="480" height="140" rx="15" fill="#23234a" stroke="#ec4899" stroke-width="2"/><text x="600" y="500" font-size="22" fill="#ec4899" font-weight="bold">DNFC — Discharged Not Final Coded</text><text x="600" y="535" font-size="19" fill="#fff">Patient discharged but coding NOT complete</text><text x="600" y="565" font-size="19" fill="#fff">DNFC feeds into DNFB (coding delay)</text><text x="600" y="590" font-size="16" fill="#888">Coding backlog indicator</text></svg>`, caption: "Middle revenue cycle: charge capture, coding, scrubbing, submission" }
    },
    {
      type: "concept",
      title: "Back End: Payment Through Collections",
      content: "The back end of the revenue cycle processes payments and resolves unpaid accounts. When the payer adjudicates the claim, they send an ERA/835 to the provider and an EOB to the patient. Payment posting applies payments, adjustments, and denials to patient accounts. Denial management is critical: denied claims must be analyzed, corrected, and resubmitted or appealed promptly. Common denial reasons include: missing/invalid authorization, coding errors, untimely filing, duplicate claim, medical necessity not established, and patient not eligible. Medicare has a 5-level appeals process: Level 1 — Redetermination (by MAC, 120 days to file), Level 2 — Reconsideration by QIC (Qualified Independent Contractor, 180 days), Level 3 — ALJ (Administrative Law Judge, amount must exceed $180, 60 days), Level 4 — Medicare Appeals Council (60 days), Level 5 — Federal District Court (amount must exceed $1,760, 60 days). After payer payment, any patient responsibility (copay, coinsurance, deductible) goes to patient billing and collections. A/R follow-up ensures outstanding accounts are pursued systematically, with aging buckets (0-30, 31-60, 61-90, 90+ days).",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Back End Revenue Cycle</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Payment Processing → Denials → Appeals → Collections</text><rect x="60" y="140" width="980" height="130" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="100" y="175" font-size="22" fill="#10b981" font-weight="bold">Payment Posting &amp; Reconciliation</text><text x="100" y="210" font-size="19" fill="#fff">ERA/835 received → Post payments, contractual adjustments, denials</text><text x="100" y="240" font-size="19" fill="#fff">Identify underpayments by comparing allowed amounts to contract terms</text><text x="100" y="265" font-size="19" fill="#888">CARCs + RARCs explain adjustment/denial reasons</text><rect x="60" y="295" width="980" height="80" rx="15" fill="rgba(239,68,68,0.15)" stroke="#ef4444" stroke-width="2"/><text x="100" y="335" font-size="22" fill="#ef4444" font-weight="bold">Top Denial Reasons: Missing auth, coding errors, untimely filing,</text><text x="100" y="365" font-size="22" fill="#ef4444">duplicate claim, medical necessity, patient ineligible</text><rect x="60" y="400" width="980" height="310" rx="18" fill="#23234a"/><text x="100" y="440" font-size="24" fill="#ffd700" font-weight="bold">5 Levels of Medicare Appeals</text><rect x="100" y="460" width="900" height="42" rx="6" fill="#1e1e3a"/><text x="120" y="488" font-size="18" fill="#10b981" font-weight="bold">Level 1</text><text x="250" y="488" font-size="18" fill="#fff">Redetermination by MAC</text><text x="680" y="488" font-size="18" fill="#888">File within 120 days</text><rect x="100" y="506" width="900" height="42" rx="6" fill="#23234a"/><text x="120" y="534" font-size="18" fill="#f59e0b" font-weight="bold">Level 2</text><text x="250" y="534" font-size="18" fill="#fff">Reconsideration by QIC</text><text x="680" y="534" font-size="18" fill="#888">File within 180 days</text><rect x="100" y="552" width="900" height="42" rx="6" fill="#1e1e3a"/><text x="120" y="580" font-size="18" fill="#8b5cf6" font-weight="bold">Level 3</text><text x="250" y="580" font-size="18" fill="#fff">ALJ Hearing (min $180)</text><text x="680" y="580" font-size="18" fill="#888">File within 60 days</text><rect x="100" y="598" width="900" height="42" rx="6" fill="#23234a"/><text x="120" y="626" font-size="18" fill="#3b82f6" font-weight="bold">Level 4</text><text x="250" y="626" font-size="18" fill="#fff">Medicare Appeals Council</text><text x="680" y="626" font-size="18" fill="#888">File within 60 days</text><rect x="100" y="644" width="900" height="42" rx="6" fill="#1e1e3a"/><text x="120" y="672" font-size="18" fill="#ef4444" font-weight="bold">Level 5</text><text x="250" y="672" font-size="18" fill="#fff">Federal District Court (min $1,760)</text><text x="680" y="672" font-size="18" fill="#888">File within 60 days</text></svg>`, caption: "Back-end revenue cycle and 5 levels of Medicare appeals" }
    },
    {
      type: "quiz",
      question: "A Medicare claim is denied. The provider disagrees and wants to appeal. What is the correct order of the first three levels of Medicare appeals?",
      options: [
        { text: "QIC Reconsideration → Redetermination by MAC → ALJ Hearing", correct: false },
        { text: "Redetermination by MAC → Reconsideration by QIC → ALJ Hearing", correct: true },
        { text: "ALJ Hearing → Redetermination by MAC → Medicare Appeals Council", correct: false },
        { text: "Redetermination by MAC → ALJ Hearing → Reconsideration by QIC", correct: false }
      ],
      explanation: "The 5 Medicare appeal levels must be followed in order: 1) Redetermination by MAC (120 days), 2) Reconsideration by QIC (180 days), 3) ALJ Hearing (60 days, min $180), 4) Medicare Appeals Council (60 days), 5) Federal District Court (60 days, min $1,760). You cannot skip levels. The most tempting wrong answer reverses levels 1 and 2 — remember 'Re-Re' (Redetermination first, then Reconsideration). Domain 4, Subtask 4.3. Difficulty: Knowledge.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Quiz: Medicare Appeals</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Five-Level Appeals Process</text><rect x="100" y="160" width="900" height="100" rx="15" fill="rgba(255,215,0,0.08)" stroke="#ffd700" stroke-width="2"/><text x="140" y="200" font-size="24" fill="#ffd700" font-weight="bold">Memory Aid: "Re-Re-ALJ-Council-Court"</text><text x="140" y="235" font-size="20" fill="#fff">Redetermination → Reconsideration → ALJ → Appeals Council → Federal Court</text><rect x="100" y="290" width="900" height="100" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="140" y="330" font-size="22" fill="#ef4444" font-weight="bold">Trap: You CANNOT skip levels in the appeals process</text><text x="140" y="365" font-size="19" fill="#fff">Each level must be exhausted before proceeding to the next</text><rect x="100" y="420" width="900" height="80" rx="15" fill="rgba(59,130,246,0.15)" stroke="#3b82f6" stroke-width="2"/><text x="140" y="470" font-size="20" fill="#3b82f6" font-weight="bold">Domain 4, Subtask 4.3 — Difficulty: Knowledge</text></svg>`, caption: "Medicare appeals must follow the 5-level sequence in order" }
    },
    {
      type: "concept",
      title: "Revenue Cycle Key Metrics",
      content: "HIM professionals must monitor key performance indicators (KPIs) to evaluate revenue cycle health. Days in Accounts Receivable (A/R) measures the average number of days it takes to collect payment after a claim is submitted. Formula: Total A/R / (Total Revenue / Number of Days). Target: less than 40 days. Higher values indicate slow collections. Clean Claim Rate is the percentage of claims accepted on first submission without edits or rejections. Formula: Clean Claims / Total Claims x 100. Target: greater than 95%. Denial Rate measures the percentage of claims denied by payers. Formula: Denied Claims / Total Claims x 100. Target: less than 5%. Case Mix Index (CMI) reflects the average complexity and resource consumption of a facility's patients. Formula: Sum of all DRG relative weights / Total number of discharges. A higher CMI means more complex (and higher-reimbursed) patients. CMI is directly impacted by CDI programs and coding accuracy. Other metrics include: coding accuracy rate, CDI query rate, CDI query agreement rate, and CC/MCC capture rate.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Revenue Cycle Metrics</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Key Performance Indicators (KPIs)</text><rect x="60" y="140" width="480" height="195" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="100" y="175" font-size="22" fill="#10b981" font-weight="bold">Days in A/R</text><text x="100" y="210" font-size="18" fill="#fff">Total A/R ÷ (Total Revenue ÷ # Days)</text><text x="100" y="240" font-size="18" fill="#f59e0b">Target: &lt; 40 days</text><text x="100" y="270" font-size="18" fill="#fff">Measures collection speed</text><text x="100" y="300" font-size="16" fill="#888">Higher = slower collections = problem</text><rect x="560" y="140" width="480" height="195" rx="18" fill="#23234a" stroke="#f59e0b" stroke-width="2"/><text x="600" y="175" font-size="22" fill="#f59e0b" font-weight="bold">Clean Claim Rate</text><text x="600" y="210" font-size="18" fill="#fff">Clean Claims ÷ Total Claims x 100</text><text x="600" y="240" font-size="18" fill="#10b981">Target: &gt; 95%</text><text x="600" y="270" font-size="18" fill="#fff">Claims accepted on first submission</text><text x="600" y="300" font-size="16" fill="#888">Lower = too many errors/edits needed</text><rect x="60" y="360" width="480" height="195" rx="18" fill="#23234a" stroke="#ef4444" stroke-width="2"/><text x="100" y="395" font-size="22" fill="#ef4444" font-weight="bold">Denial Rate</text><text x="100" y="430" font-size="18" fill="#fff">Denied Claims ÷ Total Claims x 100</text><text x="100" y="460" font-size="18" fill="#10b981">Target: &lt; 5%</text><text x="100" y="490" font-size="18" fill="#fff">Percentage of claims denied by payers</text><text x="100" y="520" font-size="16" fill="#888">Higher = revenue loss + rework needed</text><rect x="560" y="360" width="480" height="195" rx="18" fill="#23234a" stroke="#8b5cf6" stroke-width="2"/><text x="600" y="395" font-size="22" fill="#8b5cf6" font-weight="bold">Case Mix Index (CMI)</text><text x="600" y="430" font-size="18" fill="#fff">Sum DRG Weights ÷ Total Discharges</text><text x="600" y="460" font-size="18" fill="#ec4899">No fixed target — facility-specific</text><text x="600" y="490" font-size="18" fill="#fff">Average patient complexity/severity</text><text x="600" y="520" font-size="16" fill="#888">Higher CMI = higher reimbursement</text><rect x="60" y="585" width="980" height="130" rx="15" fill="rgba(255,215,0,0.08)" stroke="#ffd700" stroke-width="2"/><text x="100" y="625" font-size="22" fill="#ffd700" font-weight="bold">Exam Formulas — MEMORIZE</text><text x="100" y="660" font-size="19" fill="#fff">Days in A/R = Total A/R ÷ (Total Revenue ÷ Days in Period)</text><text x="100" y="690" font-size="19" fill="#fff">CMI = Sum of All DRG Weights ÷ Total Discharges</text></svg>`, caption: "Four critical revenue cycle metrics with formulas and targets" }
    },
    {
      type: "quiz",
      question: "A hospital had 500 discharges last month. The sum of all MS-DRG relative weights for those discharges was 750. What is the hospital's Case Mix Index (CMI)?",
      options: [
        { text: "0.67", correct: false },
        { text: "1.50", correct: true },
        { text: "250", correct: false },
        { text: "375,000", correct: false }
      ],
      explanation: "CMI = Sum of DRG Weights / Total Discharges = 750 / 500 = 1.50. A CMI of 1.50 means the average patient is 50% more resource-intensive than the national average. The trap answer 0.67 reverses the formula (500/750). The answer 250 subtracts instead of divides. The answer 375,000 multiplies instead of divides. Always set up the formula first: weights on TOP, discharges on BOTTOM. Domain 4, Subtask 4.3. Difficulty: Application.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Quiz: CMI Calculation</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Case Mix Index Formula Application</text><rect x="100" y="160" width="900" height="180" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="140" y="200" font-size="24" fill="#10b981" font-weight="bold">Worked Solution</text><text x="140" y="245" font-size="22" fill="#fff">CMI = Sum of DRG Weights ÷ Total Discharges</text><text x="140" y="280" font-size="22" fill="#fff">CMI = 750 ÷ 500</text><text x="140" y="315" font-size="26" fill="#ffd700" font-weight="bold">CMI = 1.50</text><rect x="100" y="370" width="900" height="100" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="140" y="410" font-size="22" fill="#ef4444" font-weight="bold">Trap: 0.67 reverses the formula (discharges ÷ weights)</text><text x="140" y="440" font-size="19" fill="#fff">Remember: Weights on TOP, Discharges on BOTTOM</text><rect x="100" y="500" width="900" height="80" rx="15" fill="rgba(59,130,246,0.15)" stroke="#3b82f6" stroke-width="2"/><text x="140" y="550" font-size="20" fill="#3b82f6" font-weight="bold">Domain 4, Subtask 4.3 — Difficulty: Application</text></svg>`, caption: "CMI calculation: sum of DRG weights divided by total discharges" }
    },
    {
      type: "concept",
      title: "Clinical Documentation Improvement (CDI)",
      content: "CDI programs bridge clinical documentation and coding to ensure the medical record accurately reflects the patient's severity of illness and resource consumption. CDI specialists (often nurses or HIM professionals with clinical backgrounds) perform concurrent reviews — reviewing records DURING the patient's stay, not after discharge. When documentation is ambiguous, incomplete, or inconsistent, the CDI specialist issues a physician query. Compliant queries must be: non-leading (do not suggest a specific diagnosis), based on clinical indicators in the record, open-ended or multiple-choice (not yes/no leading to a specific code), and documented as part of the medical record. Non-compliant queries include leading questions like 'Do you agree the patient has sepsis?' or 'Can you document acute respiratory failure to support the MCC?' CDI impacts CMI directly: better documentation → more accurate coding → appropriate DRG assignment → higher CC/MCC capture rate. CDI metrics include: query rate (queries issued per discharges), query agreement rate (percentage of queries where physician agrees), CC/MCC capture rate (percentage of cases with CC or MCC), and CMI impact (change in CMI attributable to CDI).",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Clinical Documentation Improvement</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Bridging Documentation and Coding</text><rect x="60" y="140" width="300" height="120" rx="15" fill="#23234a" stroke="#8b5cf6" stroke-width="2"/><text x="210" y="185" text-anchor="middle" font-size="20" fill="#8b5cf6" font-weight="bold">Clinical</text><text x="210" y="210" text-anchor="middle" font-size="20" fill="#8b5cf6" font-weight="bold">Documentation</text><text x="210" y="240" text-anchor="middle" font-size="16" fill="#888">Physician records</text><line x1="360" y1="200" x2="400" y2="200" stroke="#ffd700" stroke-width="3"/><rect x="400" y="140" width="300" height="120" rx="15" fill="#23234a" stroke="#ffd700" stroke-width="2"/><text x="550" y="185" text-anchor="middle" font-size="20" fill="#ffd700" font-weight="bold">CDI Specialist</text><text x="550" y="210" text-anchor="middle" font-size="20" fill="#ffd700" font-weight="bold">Review</text><text x="550" y="240" text-anchor="middle" font-size="16" fill="#888">Concurrent review</text><line x1="700" y1="200" x2="740" y2="200" stroke="#ffd700" stroke-width="3"/><rect x="740" y="140" width="300" height="120" rx="15" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="890" y="185" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Accurate</text><text x="890" y="210" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">Coding</text><text x="890" y="240" text-anchor="middle" font-size="16" fill="#888">Appropriate DRG</text><rect x="60" y="290" width="480" height="220" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="100" y="325" font-size="22" fill="#10b981" font-weight="bold">Compliant Query Characteristics</text><text x="100" y="360" font-size="19" fill="#fff">Non-leading (no suggested diagnosis)</text><text x="100" y="390" font-size="19" fill="#fff">Based on clinical indicators in record</text><text x="100" y="420" font-size="19" fill="#fff">Open-ended or multiple-choice format</text><text x="100" y="450" font-size="19" fill="#fff">Part of the medical record</text><text x="100" y="480" font-size="19" fill="#fff">Does not reference reimbursement</text><rect x="560" y="290" width="480" height="220" rx="18" fill="#23234a" stroke="#ef4444" stroke-width="2"/><text x="600" y="325" font-size="22" fill="#ef4444" font-weight="bold">Non-Compliant (Leading) Queries</text><text x="600" y="360" font-size="19" fill="#fff">"Do you agree pt has sepsis?"</text><text x="600" y="390" font-size="19" fill="#fff">"Can you document acute</text><text x="600" y="418" font-size="19" fill="#fff">  respiratory failure for MCC?"</text><text x="600" y="448" font-size="19" fill="#fff">Yes/No questions leading to code</text><text x="600" y="478" font-size="19" fill="#fff">Referencing DRG or reimbursement</text><rect x="60" y="540" width="980" height="150" rx="15" fill="#23234a"/><text x="100" y="575" font-size="22" fill="#f59e0b" font-weight="bold">CDI Metrics</text><text x="100" y="610" font-size="19" fill="#fff">Query Rate = Queries Issued ÷ Total Discharges</text><text x="100" y="640" font-size="19" fill="#fff">Query Agreement Rate = Physician Agrees ÷ Total Queries x 100</text><text x="100" y="670" font-size="19" fill="#fff">CC/MCC Capture Rate = Cases with CC or MCC ÷ Total Cases x 100</text></svg>`, caption: "CDI programs: compliant vs non-compliant physician queries" }
    },
    {
      type: "quiz",
      question: "A CDI specialist reviews a record and finds clinical indicators suggesting acute respiratory failure, but the physician documented only 'shortness of breath.' Which query format is COMPLIANT?",
      options: [
        { text: "'Can you add acute respiratory failure to support the MCC?'", correct: false },
        { text: "'Based on the clinical indicators (O2 sat 78%, BiPAP, ABG results), please clarify the respiratory condition: acute respiratory failure, acute exacerbation of COPD, or other.'", correct: true },
        { text: "'Do you agree the patient has acute respiratory failure? Yes or No.'", correct: false },
        { text: "'The DRG would increase if you documented respiratory failure. Can you update?'", correct: false }
      ],
      explanation: "A compliant query must be non-leading, reference clinical indicators, and offer multiple choices without suggesting a specific answer. Option B meets all criteria: it cites specific clinical evidence (O2 sat, BiPAP, ABG) and offers multiple diagnostic options. Option A is leading (suggests specific diagnosis for MCC). Option C is yes/no leading to one answer. Option D references reimbursement, which is non-compliant. Domain 4, Subtask 4.3. Difficulty: Application.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Quiz: Compliant CDI Query</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Non-Leading Physician Query Format</text><rect x="100" y="160" width="900" height="150" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="140" y="200" font-size="22" fill="#10b981" font-weight="bold">Compliant Query Elements (All Must Be Present)</text><text x="140" y="240" font-size="19" fill="#fff">1. References specific clinical indicators from the record</text><text x="140" y="270" font-size="19" fill="#fff">2. Offers multiple diagnostic choices (not yes/no)</text><text x="140" y="300" font-size="19" fill="#fff">3. Does NOT suggest a specific diagnosis or mention reimbursement</text><rect x="100" y="340" width="900" height="120" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="140" y="380" font-size="22" fill="#ef4444" font-weight="bold">Never Reference Reimbursement in a Query</text><text x="140" y="415" font-size="19" fill="#fff">"DRG would increase" or "support the MCC" = NON-COMPLIANT</text><text x="140" y="445" font-size="19" fill="#888">This crosses the line from documentation improvement to upcoding</text></svg>`, caption: "Compliant CDI queries are non-leading and evidence-based" }
    },
    {
      type: "quiz",
      question: "A hospital's total accounts receivable is $6,000,000 and average daily revenue is $200,000. What are the days in A/R, and does this meet the benchmark?",
      options: [
        { text: "30 days — meets the benchmark of <40 days", correct: true },
        { text: "33.3 days — exceeds the benchmark of <30 days", correct: false },
        { text: "3 days — well below the benchmark", correct: false },
        { text: "Cannot be calculated without more information", correct: false }
      ],
      explanation: "Days in A/R = Total A/R / Average Daily Revenue = $6,000,000 / $200,000 = 30 days. The industry benchmark target is less than 40 days, so 30 days meets the benchmark. The trap answer claims the benchmark is <30 days — the standard benchmark is <40 days. Option C of 3 days results from dividing revenue by A/R (reversed formula). Always remember: A/R on TOP, daily revenue on BOTTOM. Domain 4, Subtask 4.3. Difficulty: Application.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Quiz: Days in A/R</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Revenue Cycle Metric Calculation</text><rect x="100" y="160" width="900" height="180" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="140" y="200" font-size="24" fill="#10b981" font-weight="bold">Worked Solution</text><text x="140" y="240" font-size="22" fill="#fff">Days in A/R = Total A/R ÷ Average Daily Revenue</text><text x="140" y="275" font-size="22" fill="#fff">= $6,000,000 ÷ $200,000</text><text x="140" y="315" font-size="26" fill="#ffd700" font-weight="bold">= 30 days (MEETS benchmark of &lt;40 days)</text><rect x="100" y="370" width="900" height="100" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="140" y="410" font-size="22" fill="#ef4444" font-weight="bold">Benchmark is &lt;40 days, NOT &lt;30 days</text><text x="140" y="445" font-size="19" fill="#fff">Also remember: A/R on TOP, daily revenue on BOTTOM (never reverse)</text></svg>`, caption: "Days in A/R calculation with benchmark comparison" }
    },
    {
      type: "visual",
      title: "EXAM TIP: Revenue Cycle Step Ordering",
      content: "The RHIT exam frequently asks you to identify which step comes first, next, or is out of order in the revenue cycle. Memorize this sequence as a story: A patient CALLS to schedule (scheduling), gives basic info before arriving (pre-registration), staff confirms insurance is active (verification), gets payer approval for the procedure (pre-authorization), checks in and signs forms (registration), receives care, charges are captured (charge capture), HIM codes the record (coding), software checks for errors (scrubbing), claim goes to payer (837 submission), payer sends payment info (835 remittance), staff posts the payment (payment posting), denied claims get worked (denial management), formal disputes filed (appeals), and remaining balances collected (collections/A/R follow-up). If you can tell this story, you can answer any sequencing question.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Revenue Cycle Sequence</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Memorize This Order for Exam Questions</text><rect x="100" y="130" width="900" height="80" rx="15" fill="rgba(255,215,0,0.15)" stroke="#ffd700" stroke-width="2"/><text x="550" y="180" text-anchor="middle" fill="#ffd700" font-weight="bold" font-size="32">EXAM TIP</text><rect x="80" y="240" width="250" height="55" rx="10" fill="#23234a" stroke="#10b981" stroke-width="1"/><text x="205" y="275" text-anchor="middle" font-size="17" fill="#10b981">1. Scheduling</text><rect x="350" y="240" width="250" height="55" rx="10" fill="#23234a" stroke="#10b981" stroke-width="1"/><text x="475" y="275" text-anchor="middle" font-size="17" fill="#10b981">2. Pre-registration</text><rect x="620" y="240" width="250" height="55" rx="10" fill="#23234a" stroke="#10b981" stroke-width="1"/><text x="745" y="275" text-anchor="middle" font-size="17" fill="#10b981">3. Insurance Verify</text><rect x="80" y="310" width="250" height="55" rx="10" fill="#23234a" stroke="#10b981" stroke-width="1"/><text x="205" y="345" text-anchor="middle" font-size="17" fill="#10b981">4. Pre-authorization</text><rect x="350" y="310" width="250" height="55" rx="10" fill="#23234a" stroke="#10b981" stroke-width="1"/><text x="475" y="345" text-anchor="middle" font-size="17" fill="#10b981">5. Registration</text><rect x="620" y="310" width="250" height="55" rx="10" fill="#23234a" stroke="#f59e0b" stroke-width="1"/><text x="745" y="345" text-anchor="middle" font-size="17" fill="#f59e0b">6. Charge Capture</text><rect x="80" y="380" width="250" height="55" rx="10" fill="#23234a" stroke="#f59e0b" stroke-width="1"/><text x="205" y="415" text-anchor="middle" font-size="17" fill="#f59e0b">7. Coding (HIM)</text><rect x="350" y="380" width="250" height="55" rx="10" fill="#23234a" stroke="#f59e0b" stroke-width="1"/><text x="475" y="415" text-anchor="middle" font-size="17" fill="#f59e0b">8. Claim Scrubbing</text><rect x="620" y="380" width="250" height="55" rx="10" fill="#23234a" stroke="#f59e0b" stroke-width="1"/><text x="745" y="415" text-anchor="middle" font-size="17" fill="#f59e0b">9. Claim Submit (837)</text><rect x="80" y="450" width="250" height="55" rx="10" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="205" y="485" text-anchor="middle" font-size="17" fill="#ef4444">10. Remittance (835)</text><rect x="350" y="450" width="250" height="55" rx="10" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="475" y="485" text-anchor="middle" font-size="17" fill="#ef4444">11. Payment Posting</text><rect x="620" y="450" width="250" height="55" rx="10" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="745" y="485" text-anchor="middle" font-size="17" fill="#ef4444">12. Denial Mgmt</text><rect x="80" y="520" width="250" height="55" rx="10" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="205" y="555" text-anchor="middle" font-size="17" fill="#ef4444">13. Appeals</text><rect x="350" y="520" width="250" height="55" rx="10" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="475" y="555" text-anchor="middle" font-size="17" fill="#ef4444">14. Collections/A/R</text><rect x="60" y="610" width="980" height="80" rx="15" fill="rgba(16,185,129,0.1)" stroke="#10b981" stroke-width="1"/><text x="100" y="645" font-size="20" fill="#10b981" font-weight="bold">Green = Front End | Yellow = Middle | Red = Back End</text><text x="100" y="675" font-size="18" fill="#888">Tell the story: patient calls → info gathered → care delivered → coded → billed → paid → followed up</text></svg>`, caption: "Complete 14-step revenue cycle sequence for exam ordering questions" }
    },
    {
      type: "visual",
      title: "HIGH-YIELD FACTS: Revenue Cycle Operations",
      content: "These are the most frequently tested revenue cycle facts on the RHIT exam. Commit them to memory as a consolidated reference sheet. Focus on the metric targets, DNFB/DNFC definitions, CDI query compliance rules, and the Medicare appeals sequence.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Revenue Cycle Quick Reference</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">High-Yield Exam Review</text><rect x="100" y="130" width="900" height="80" rx="15" fill="rgba(59,130,246,0.15)" stroke="#3b82f6" stroke-width="2"/><text x="550" y="180" text-anchor="middle" fill="#3b82f6" font-weight="bold" font-size="32">HIGH-YIELD FACTS</text><rect x="60" y="240" width="480" height="210" rx="15" fill="#23234a"/><text x="100" y="275" font-size="22" fill="#10b981" font-weight="bold">Metric Targets</text><text x="100" y="310" font-size="19" fill="#fff">Days in A/R: &lt; 40 days</text><text x="100" y="340" font-size="19" fill="#fff">Clean claim rate: &gt; 95%</text><text x="100" y="370" font-size="19" fill="#fff">Denial rate: &lt; 5%</text><text x="100" y="400" font-size="19" fill="#fff">CMI: facility-specific (no universal target)</text><text x="100" y="430" font-size="19" fill="#fff">DNFB: minimize days to zero</text><rect x="560" y="240" width="480" height="210" rx="15" fill="#23234a"/><text x="600" y="275" font-size="22" fill="#ef4444" font-weight="bold">Top Denial Reasons</text><text x="600" y="310" font-size="19" fill="#fff">1. Missing/invalid pre-authorization</text><text x="600" y="340" font-size="19" fill="#fff">2. Coding errors (invalid codes)</text><text x="600" y="370" font-size="19" fill="#fff">3. Untimely filing (missed deadline)</text><text x="600" y="400" font-size="19" fill="#fff">4. Duplicate claim submission</text><text x="600" y="430" font-size="19" fill="#fff">5. Medical necessity not met</text><rect x="60" y="480" width="480" height="180" rx="15" fill="#23234a"/><text x="100" y="515" font-size="22" fill="#8b5cf6" font-weight="bold">CDI Query Rules</text><text x="100" y="550" font-size="19" fill="#fff">Non-leading (no suggested Dx)</text><text x="100" y="578" font-size="19" fill="#fff">Based on clinical indicators</text><text x="100" y="606" font-size="19" fill="#fff">Multiple choice (not yes/no)</text><text x="100" y="634" font-size="19" fill="#fff">NEVER reference reimbursement</text><rect x="560" y="480" width="480" height="180" rx="15" fill="#23234a"/><text x="600" y="515" font-size="22" fill="#ffd700" font-weight="bold">Medicare Appeals (in order)</text><text x="600" y="550" font-size="19" fill="#fff">1. Redetermination (MAC, 120d)</text><text x="600" y="578" font-size="19" fill="#fff">2. Reconsideration (QIC, 180d)</text><text x="600" y="606" font-size="19" fill="#fff">3. ALJ Hearing (60d, min $180)</text><text x="600" y="634" font-size="19" fill="#fff">4. Appeals Council → 5. Fed Court</text></svg>`, caption: "High-yield revenue cycle facts for exam day" }
    },
    {
      type: "quiz",
      question: "DNFB (Discharged Not Final Billed) most directly impacts which revenue cycle metric?",
      options: [
        { text: "Clean claim rate", correct: false },
        { text: "Denial rate", correct: false },
        { text: "Days in accounts receivable", correct: true },
        { text: "Case mix index", correct: false }
      ],
      explanation: "DNFB directly increases days in A/R because discharged patients whose claims have not been submitted represent revenue sitting uncollected. The longer claims remain unbilled, the longer it takes to receive payment, inflating A/R days. Clean claim rate measures claims accepted on first submission (not related to unbilled claims). Denial rate measures rejected claims (claims that were submitted). CMI measures patient acuity. The trap is 'denial rate' — DNFB claims have NOT been submitted yet, so they cannot be denied. Domain 4, Subtask 4.3. Difficulty: Comprehension.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Quiz: DNFB Impact</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Discharged Not Final Billed</text><rect x="100" y="160" width="900" height="160" rx="18" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="140" y="200" font-size="24" fill="#10b981" font-weight="bold">DNFB → Delayed Billing → Higher Days in A/R</text><text x="140" y="240" font-size="20" fill="#fff">Patient discharged but claim NOT submitted = revenue uncollected</text><text x="140" y="275" font-size="20" fill="#fff">The longer DNFB persists, the longer it takes to get paid</text><text x="140" y="305" font-size="20" fill="#888">DNFB is a BILLING delay, not a coding accuracy issue</text><rect x="100" y="350" width="900" height="100" rx="15" fill="rgba(239,68,68,0.1)" stroke="#ef4444" stroke-width="2"/><text x="140" y="390" font-size="22" fill="#ef4444" font-weight="bold">Trap: DNFB claims have NOT been submitted yet</text><text x="140" y="425" font-size="19" fill="#fff">They cannot be denied (denial rate) because they have not reached the payer</text></svg>`, caption: "DNFB delays billing, directly increasing days in A/R" }
    },
    {
      type: "concept",
      title: "TRAP ALERT: Revenue Cycle Confusions",
      content: "Trap 1: DNFB vs DNFC — DNFB (Discharged Not Final Billed) means the claim has not been SUBMITTED. DNFC (Discharged Not Final Coded) means coding is not COMPLETE. DNFC is a subset of DNFB — you cannot bill what you have not coded. Trap 2: 837 vs 835 direction — 837 goes FROM provider TO payer (claim submission). 835 comes FROM payer TO provider (remittance/payment). Trap 3: CDI concurrent vs retrospective — CDI review is concurrent (DURING the stay). Coding is typically retrospective (AFTER discharge). CDI happens while there is still time to query the physician and impact documentation. Trap 4: CMI calculation — DRG weights on TOP, discharges on BOTTOM. Never reverse. Trap 5: Clean claim rate includes ALL claims, not just paid ones — a clean claim passes edits on first submission regardless of payment outcome. Trap 6: Pre-authorization vs authorization — pre-auth is obtained BEFORE the service; authorization may refer to patient consent for information release.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Revenue Cycle Traps</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Commonly Confused Concepts</text><rect x="100" y="130" width="900" height="80" rx="15" fill="rgba(239,68,68,0.15)" stroke="#ef4444" stroke-width="2"/><text x="550" y="180" text-anchor="middle" fill="#ef4444" font-weight="bold" font-size="32">TRAP ALERT</text><rect x="60" y="240" width="480" height="120" rx="12" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="80" y="275" font-size="20" fill="#ef4444" font-weight="bold">DNFB vs DNFC</text><text x="80" y="305" font-size="18" fill="#fff">DNFB = not BILLED (claim not sent)</text><text x="80" y="330" font-size="18" fill="#fff">DNFC = not CODED (coding incomplete)</text><text x="80" y="355" font-size="16" fill="#888">DNFC causes DNFB (can't bill w/o codes)</text><rect x="560" y="240" width="480" height="120" rx="12" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="580" y="275" font-size="20" fill="#ef4444" font-weight="bold">837 vs 835 Direction</text><text x="580" y="305" font-size="18" fill="#fff">837: Provider → Payer (CLAIM)</text><text x="580" y="330" font-size="18" fill="#fff">835: Payer → Provider (PAYMENT)</text><text x="580" y="355" font-size="16" fill="#888">Opposite directions!</text><rect x="60" y="380" width="480" height="120" rx="12" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="80" y="415" font-size="20" fill="#ef4444" font-weight="bold">CDI Timing</text><text x="80" y="445" font-size="18" fill="#fff">CDI = CONCURRENT (during stay)</text><text x="80" y="470" font-size="18" fill="#fff">Coding = typically after discharge</text><text x="80" y="495" font-size="16" fill="#888">CDI queries physician while still treating</text><rect x="560" y="380" width="480" height="120" rx="12" fill="#23234a" stroke="#ef4444" stroke-width="1"/><text x="580" y="415" font-size="20" fill="#ef4444" font-weight="bold">CMI Formula Direction</text><text x="580" y="445" font-size="18" fill="#fff">DRG weights on TOP (numerator)</text><text x="580" y="470" font-size="18" fill="#fff">Discharges on BOTTOM (denominator)</text><text x="580" y="495" font-size="16" fill="#888">Reversing = completely wrong answer</text></svg>`, caption: "Common revenue cycle traps to avoid on the RHIT exam" }
    },
    {
      type: "application",
      title: "Apply It: Revenue Cycle in HIM Practice",
      content: "As an HIM professional, you are embedded in the revenue cycle at multiple points. In coding, you assign the diagnosis and procedure codes that drive DRG assignment and reimbursement. In CDI, you or your colleagues review documentation concurrently and issue queries to ensure accuracy. In claim scrubbing, your department validates code combinations before submission. In denial management, you analyze denied claims, determine if coding was the cause, and either correct and resubmit or prepare appeals documentation. In compliance monitoring, you track metrics like CMI, coding accuracy rate, and query agreement rate to detect potential upcoding or undercoding patterns. On the RHIT exam, revenue cycle questions will test your ability to: sequence revenue cycle steps correctly, calculate metrics (CMI, days in A/R), identify compliant vs non-compliant CDI queries, match Medicare appeal levels, and distinguish DNFB from DNFC. Master these concepts and you will excel on the Domain 4 revenue cycle questions.",
      visual: { type: "diagram", svg: `<svg viewBox="0 0 1100 1100" class="lesson-visual"><rect x="0" y="0" width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="55" text-anchor="middle" font-size="42" fill="#ffd700" font-weight="bold">Apply It: HIM in Revenue Cycle</text><text x="550" y="100" text-anchor="middle" font-size="29" fill="#888">Your Role at Every Stage</text><rect x="60" y="150" width="310" height="140" rx="15" fill="#23234a" stroke="#8b5cf6" stroke-width="2"/><text x="215" y="190" text-anchor="middle" font-size="20" fill="#8b5cf6" font-weight="bold">Coding</text><text x="80" y="220" font-size="17" fill="#fff">Assign ICD/CPT codes</text><text x="80" y="245" font-size="17" fill="#fff">Drive DRG assignment</text><text x="80" y="270" font-size="17" fill="#fff">Impact reimbursement</text><rect x="395" y="150" width="310" height="140" rx="15" fill="#23234a" stroke="#10b981" stroke-width="2"/><text x="550" y="190" text-anchor="middle" font-size="20" fill="#10b981" font-weight="bold">CDI Review</text><text x="415" y="220" font-size="17" fill="#fff">Concurrent review</text><text x="415" y="245" font-size="17" fill="#fff">Physician queries</text><text x="415" y="270" font-size="17" fill="#fff">CC/MCC capture</text><rect x="730" y="150" width="310" height="140" rx="15" fill="#23234a" stroke="#f59e0b" stroke-width="2"/><text x="885" y="190" text-anchor="middle" font-size="20" fill="#f59e0b" font-weight="bold">Claim Scrubbing</text><text x="750" y="220" font-size="17" fill="#fff">Code validation</text><text x="750" y="245" font-size="17" fill="#fff">NCCI edit checks</text><text x="750" y="270" font-size="17" fill="#fff">Error prevention</text><rect x="60" y="320" width="310" height="140" rx="15" fill="#23234a" stroke="#ef4444" stroke-width="2"/><text x="215" y="360" text-anchor="middle" font-size="20" fill="#ef4444" font-weight="bold">Denial Management</text><text x="80" y="390" font-size="17" fill="#fff">Analyze denials</text><text x="80" y="415" font-size="17" fill="#fff">Correct and resubmit</text><text x="80" y="440" font-size="17" fill="#fff">Prepare appeals</text><rect x="395" y="320" width="310" height="140" rx="15" fill="#23234a" stroke="#3b82f6" stroke-width="2"/><text x="550" y="360" text-anchor="middle" font-size="20" fill="#3b82f6" font-weight="bold">Compliance</text><text x="415" y="390" font-size="17" fill="#fff">Monitor CMI trends</text><text x="415" y="415" font-size="17" fill="#fff">Coding accuracy audits</text><text x="415" y="440" font-size="17" fill="#fff">Detect upcoding patterns</text><rect x="730" y="320" width="310" height="140" rx="15" fill="#23234a" stroke="#ec4899" stroke-width="2"/><text x="885" y="360" text-anchor="middle" font-size="20" fill="#ec4899" font-weight="bold">A/R Follow-up</text><text x="750" y="390" font-size="17" fill="#fff">Track aging accounts</text><text x="750" y="415" font-size="17" fill="#fff">Work unpaid claims</text><text x="750" y="440" font-size="17" fill="#fff">Reduce days in A/R</text><rect x="60" y="500" width="980" height="80" rx="15" fill="rgba(255,215,0,0.1)" stroke="#ffd700" stroke-width="2"/><text x="100" y="540" font-size="22" fill="#ffd700" font-weight="bold">RHIT Exam: Expect 6-8 questions on revenue cycle operations,</text><text x="100" y="570" font-size="22" fill="#ffd700">metric calculations, CDI compliance, and appeals sequencing</text></svg>`, caption: "HIM professionals touch every stage of the revenue cycle" }
    }
  ]
