                                                            svg:  "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n            <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n            <text x=\"550\" y=\"55\" font-size=\"42\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Study Checklist: Lesson 7</text>\n            <text x=\"550\" y=\"100\" font-size=\"29\" fill=\"#888\" text-anchor=\"middle\">HIPAA Privacy Rule — Key Numbers</text>\n            <rect x=\"60\" y=\"130\" width=\"980\" height=\"60\" rx=\"12\" fill=\"#23234a\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n            <text x=\"100\" y=\"168\" font-size=\"22\" fill=\"#6366f1\" font-weight=\"bold\">Timeline</text>\n            <text x=\"400\" y=\"168\" font-size=\"22\" fill=\"#6366f1\" font-weight=\"bold\">Right/Rule</text>\n            <rect x=\"60\" y=\"195\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.03)\"/>\n            <text x=\"100\" y=\"222\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">30 days</text>\n            <text x=\"400\" y=\"222\" font-size=\"20\" fill=\"#fff\">Right of Access (+30 day extension)</text>\n            <rect x=\"60\" y=\"240\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.06)\"/>\n            <text x=\"100\" y=\"267\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">60 days</text>\n            <text x=\"400\" y=\"267\" font-size=\"20\" fill=\"#fff\">Right to Amendment (+30 day extension)</text>\n            <rect x=\"60\" y=\"285\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.03)\"/>\n            <text x=\"100\" y=\"312\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">6 years</text>\n            <text x=\"400\" y=\"312\" font-size=\"20\" fill=\"#fff\">Accounting of Disclosures lookback</text>\n            <rect x=\"60\" y=\"330\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.06)\"/>\n            <text x=\"100\" y=\"357\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">50 years</text>\n            <text x=\"400\" y=\"357\" font-size=\"20\" fill=\"#fff\">Deceased patient protection</text>\n            <rect x=\"60\" y=\"375\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.03)\"/>\n            <text x=\"100\" y=\"402\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">18</text>\n            <text x=\"400\" y=\"402\" font-size=\"20\" fill=\"#fff\">HIPAA identifiers (Safe Harbor removal)</text>\n            <rect x=\"60\" y=\"420\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.06)\"/>\n            <text x=\"100\" y=\"447\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">6 + 3</text>\n            <text x=\"400\" y=\"447\" font-size=\"20\" fill=\"#fff\">Authorization elements + required statements</text>\n            <rect x=\"60\" y=\"465\" width=\"980\" height=\"40\" rx=\"5\" fill=\"rgba(255,255,255,0.03)\"/>\n            <text x=\"100\" y=\"492\" font-size=\"20\" fill=\"#ef4444\" font-weight=\"bold\">3</text>\n            <text x=\"400\" y=\"492\" font-size=\"20\" fill=\"#fff\">Types of covered entities</text>\n            <rect x=\"60\" y=\"530\" width=\"980\" height=\"80\" rx=\"15\" fill=\"rgba(239,68,68,0.15)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n            <text x=\"550\" y=\"565\" text-anchor=\"middle\" fill=\"#ef4444\" font-size=\"22\" font-weight=\"bold\">TOP TRAPS: Access=30d (not 60) | Psych notes=ALWAYS separate auth</text>\n            <text x=\"550\" y=\"595\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Self-pay=MUST restrict | 42 CFR Part 2 > HIPAA | Min necessary excludes treatment</text>\n          </svg>",
