                                        {
                                                  type:  "quiz",
                                                  title:  "MSP Rules Quiz",
                                                  question:  "A 67-year-old Medicare beneficiary is still employed at a company with 25 employees and has group health insurance through the employer. Which payer is primary?",
                                                  options:  [
                                                            {
                                                                      text:  "Medicare is primary because the patient is over 65",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "The employer group health plan is primary under the working aged MSP rule",
                                                                      correct:  true
                                                            },
                                                            {
                                                                      text:  "The patient can choose which plan is primary",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "Both plans split the payment 50/50 under COB rules",
                                                                      correct:  false
                                                            }
                                                  ],
                                                  explanation:  "Under the Medicare Secondary Payer (MSP) 'working aged' rule, when a Medicare beneficiary age 65+ is covered by an employer group health plan and the employer has 20 or more employees, the employer plan is PRIMARY and Medicare is SECONDARY. The 20-employee threshold is met here (25 employees). The patient cannot choose — MSP rules are mandatory under federal law. The 50/50 split option does not exist in COB. This is the most commonly tested MSP scenario on the RHIT exam.",
                                                  visual:  {
                                                            type:  "diagram",
                                                            svg:  "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" font-size=\"42\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Working Aged MSP Rule</text><text x=\"550\" y=\"95\" font-size=\"29\" fill=\"#888\" text-anchor=\"middle\">Age 65+ with Employer Coverage (20+ employees)</text><rect x=\"150\" y=\"140\" width=\"800\" height=\"120\" rx=\"16\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"185\" font-size=\"26\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">Employer GHP = PRIMARY</text><text x=\"550\" y=\"225\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">Medicare = SECONDARY (pays remaining balance)</text><rect x=\"150\" y=\"290\" width=\"800\" height=\"100\" rx=\"14\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"170\" y=\"325\" font-size=\"22\" fill=\"#f59e0b\" font-weight=\"bold\">Key Threshold: Employer must have 20+ employees</text><text x=\"170\" y=\"358\" font-size=\"20\" fill=\"#fff\">This patient: 25 employees — threshold met. GHP is primary.</text></svg>",
                                                            caption:  "Working aged MSP rule — employer plan is primary when 20+ employees"
                                                  }
                                        },
                                        {
                                                  type:  "quiz",
                                                  title:  "Hospice Payment Quiz",
                                                  question:  "Under the Medicare Hospice benefit, which of the following represents the four levels of hospice care used to determine per diem payment rates?",
                                                  options:  [
                                                            {
                                                                      text:  "Skilled, intermediate, custodial, and palliative care",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "Routine home care, continuous home care, inpatient respite care, and general inpatient care",
                                                                      correct:  true
                                                            },
                                                            {
                                                                      text:  "Home care, SNF care, hospital care, and emergency care",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "Levels 1-4 based on patient functional status score",
                                                                      correct:  false
                                                            }
                                                  ],
                                                  explanation:  "Medicare Hospice has exactly four levels of care: (1) Routine Home Care — the most common level, provided at home, lowest per diem rate; (2) Continuous Home Care — at least 8 hours of nursing care at home during a crisis period; (3) Inpatient Respite Care — short-term inpatient care (up to 5 days) to give the caregiver a break; (4) General Inpatient Care — pain control or acute symptom management that cannot be provided at home. Each level has a different per diem rate. The other options describe care settings, not hospice payment levels.",
                                                  visual:  {
                                                            type:  "diagram",
                                                            svg:  "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" font-size=\"42\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Hospice: 4 Levels of Care</text><text x=\"550\" y=\"95\" font-size=\"29\" fill=\"#888\" text-anchor=\"middle\">Each Level Has a Different Per Diem Rate</text><rect x=\"60\" y=\"130\" width=\"490\" height=\"130\" rx=\"16\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"80\" y=\"165\" font-size=\"22\" fill=\"#10b981\" font-weight=\"bold\">1. Routine Home Care</text><text x=\"80\" y=\"198\" font-size=\"20\" fill=\"#fff\">Most common level</text><text x=\"80\" y=\"228\" font-size=\"20\" fill=\"#fff\">Standard hospice at home</text><text x=\"80\" y=\"250\" font-size=\"18\" fill=\"#888\">Lowest per diem rate</text><rect x=\"570\" y=\"130\" width=\"470\" height=\"130\" rx=\"16\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"590\" y=\"165\" font-size=\"22\" fill=\"#f59e0b\" font-weight=\"bold\">2. Continuous Home Care</text><text x=\"590\" y=\"198\" font-size=\"20\" fill=\"#fff\">8+ hours nursing at home</text><text x=\"590\" y=\"228\" font-size=\"20\" fill=\"#fff\">During crisis period only</text><text x=\"590\" y=\"250\" font-size=\"18\" fill=\"#888\">Higher rate for intensive home care</text><rect x=\"60\" y=\"285\" width=\"490\" height=\"130\" rx=\"16\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"80\" y=\"320\" font-size=\"22\" fill=\"#8b5cf6\" font-weight=\"bold\">3. Inpatient Respite Care</text><text x=\"80\" y=\"353\" font-size=\"20\" fill=\"#fff\">Short inpatient stay (max 5 days)</text><text x=\"80\" y=\"383\" font-size=\"20\" fill=\"#fff\">Gives caregiver a break</text><text x=\"80\" y=\"405\" font-size=\"18\" fill=\"#888\">Facility-based, limited duration</text><rect x=\"570\" y=\"285\" width=\"470\" height=\"130\" rx=\"16\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"590\" y=\"320\" font-size=\"22\" fill=\"#ef4444\" font-weight=\"bold\">4. General Inpatient Care</text><text x=\"590\" y=\"353\" font-size=\"20\" fill=\"#fff\">Acute symptom management</text><text x=\"590\" y=\"383\" font-size=\"20\" fill=\"#fff\">Pain control in facility</text><text x=\"590\" y=\"405\" font-size=\"18\" fill=\"#888\">Highest per diem rate</text></svg>",
                                                            caption:  "The four levels of Medicare Hospice care with per diem payment"
                                                  }
                                        }
