                                                  type:  "quiz",
                                                  title:  "MACRA Tracks Quiz",
                                                  question:  "A physician practice is evaluating whether to pursue Advanced APM status under MACRA. Which of the following is a benefit of qualifying as an Advanced APM participant?",
                                                  options:  [
                                                            {
                                                                      text:  "The practice receives a 9% Medicare payment bonus",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "The practice is exempt from MIPS reporting and receives a 5% lump-sum bonus",
                                                                      correct:  true
                                                            },
                                                            {
                                                                      text:  "The practice is exempt from all quality reporting requirements permanently",
                                                                      correct:  false
                                                            },
                                                            {
                                                                      text:  "The practice receives automatic 5-star quality ratings",
                                                                      correct:  false
                                                            }
                                                  ],
                                                  explanation:  "Advanced APM **Qualifying Participants (QPs)** receive a **5% lump-sum bonus** on Medicare Part B payments and are **exempt from MIPS** reporting and payment adjustments. The bonus is 5%, not 9% (which is the maximum MIPS adjustment). They are not exempt from all quality reporting — APMs have their own quality requirements. Star ratings are for MA plans, not APMs.",
                                                  visual:  {
                                                            type:  "diagram",
                                                            svg:  "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" font-size=\"42\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">MIPS vs Advanced APM</text><rect x=\"60\" y=\"130\" width=\"460\" height=\"250\" rx=\"18\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"290\" y=\"170\" font-size=\"26\" fill=\"#6366f1\" text-anchor=\"middle\" font-weight=\"bold\">MIPS Track</text><text x=\"100\" y=\"210\" font-size=\"21\" fill=\"#fff\">Must report 4 categories</text><text x=\"100\" y=\"245\" font-size=\"21\" fill=\"#fff\">Score 0-100</text><text x=\"100\" y=\"280\" font-size=\"21\" fill=\"#fff\">Adjustment: -9% to +9%</text><text x=\"100\" y=\"315\" font-size=\"21\" fill=\"#fff\">Applied 2 years later</text><text x=\"100\" y=\"350\" font-size=\"20\" fill=\"#888\">Most Medicare clinicians</text><rect x=\"580\" y=\"130\" width=\"460\" height=\"250\" rx=\"18\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"810\" y=\"170\" font-size=\"26\" fill=\"#8b5cf6\" text-anchor=\"middle\" font-weight=\"bold\">Advanced APM Track</text><text x=\"620\" y=\"210\" font-size=\"21\" fill=\"#10b981\">✓ Exempt from MIPS</text><text x=\"620\" y=\"245\" font-size=\"21\" fill=\"#10b981\">✓ 5% lump-sum bonus</text><text x=\"620\" y=\"280\" font-size=\"21\" fill=\"#fff\">Must bear financial risk</text><text x=\"620\" y=\"315\" font-size=\"21\" fill=\"#fff\">Use certified EHR technology</text><text x=\"620\" y=\"350\" font-size=\"20\" fill=\"#888\">Must meet QP threshold</text></svg>",
                                                            caption:  "Comparing MIPS and Advanced APM tracks under MACRA"
                                                  }
